-- Production Restaurant & F&B: tenant-scoped outlets, POS, kitchen, recipe consumption, settlement, procurement, audit, and alerts.
BEGIN;

CREATE TABLE IF NOT EXISTS public.restaurant_outlets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, property_id uuid REFERENCES public.hospitality_properties(id) ON DELETE SET NULL, branch_id uuid REFERENCES public.branches(id) ON DELETE SET NULL, name text NOT NULL, code text, timezone text NOT NULL DEFAULT 'Africa/Dar_es_Salaam', currency text NOT NULL DEFAULT 'TZS', tax_rate numeric(9,6) NOT NULL DEFAULT 0, service_charge_rate numeric(9,6) NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'Active' CHECK(status IN ('Active','Inactive')), data jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,name));
CREATE TABLE IF NOT EXISTS public.restaurant_dining_areas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, outlet_id uuid NOT NULL REFERENCES public.restaurant_outlets(id) ON DELETE CASCADE, name text NOT NULL, area_type text NOT NULL DEFAULT 'Dining', layout jsonb NOT NULL DEFAULT '{}'::jsonb, status text NOT NULL DEFAULT 'Active' CHECK(status IN ('Active','Inactive')), UNIQUE(outlet_id,name));
CREATE TABLE IF NOT EXISTS public.restaurant_tables (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, outlet_id uuid NOT NULL REFERENCES public.restaurant_outlets(id) ON DELETE CASCADE, area_id uuid REFERENCES public.restaurant_dining_areas(id) ON DELETE SET NULL, code text NOT NULL, capacity integer NOT NULL DEFAULT 2 CHECK(capacity>0), status text NOT NULL DEFAULT 'Available' CHECK(status IN ('Available','Reserved','Occupied','Cleaning','Blocked')), position jsonb NOT NULL DEFAULT '{}'::jsonb, current_order_id uuid, data jsonb NOT NULL DEFAULT '{}'::jsonb, updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(outlet_id,code));
CREATE TABLE IF NOT EXISTS public.restaurant_staff_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, outlet_id uuid REFERENCES public.restaurant_outlets(id) ON DELETE CASCADE, employee_id uuid NOT NULL REFERENCES public.hr_employees(id) ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('Restaurant Manager','Cashier','Waiter','Kitchen','Bar','Storekeeper','Finance')), status text NOT NULL DEFAULT 'Active' CHECK(status IN ('Active','Inactive')), UNIQUE(outlet_id,employee_id,role));
CREATE TABLE IF NOT EXISTS public.restaurant_shifts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, outlet_id uuid NOT NULL REFERENCES public.restaurant_outlets(id) ON DELETE CASCADE, employee_id uuid NOT NULL REFERENCES public.hr_employees(id) ON DELETE RESTRICT, role text NOT NULL, starts_at timestamptz NOT NULL, ends_at timestamptz, status text NOT NULL DEFAULT 'Open' CHECK(status IN ('Open','Closed','Cancelled')), opening_cash numeric(18,2) NOT NULL DEFAULT 0, closing_cash numeric(18,2), data jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.restaurant_menu_categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, outlet_id uuid NOT NULL REFERENCES public.restaurant_outlets(id) ON DELETE CASCADE, name text NOT NULL, sort_order integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'Active' CHECK(status IN ('Active','Inactive')), UNIQUE(outlet_id,name));
CREATE TABLE IF NOT EXISTS public.restaurant_menu_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, outlet_id uuid NOT NULL REFERENCES public.restaurant_outlets(id) ON DELETE CASCADE, category_id uuid REFERENCES public.restaurant_menu_categories(id) ON DELETE SET NULL, inventory_item_id uuid REFERENCES public.inventory_items(id) ON DELETE SET NULL, sku text, name text NOT NULL, description text, price numeric(18,2) NOT NULL DEFAULT 0 CHECK(price>=0), cost_price numeric(18,2) NOT NULL DEFAULT 0 CHECK(cost_price>=0), preparation_minutes integer NOT NULL DEFAULT 0, station text NOT NULL DEFAULT 'Kitchen', tax_rate numeric(9,6), status text NOT NULL DEFAULT 'Active' CHECK(status IN ('Active','Inactive')), data jsonb NOT NULL DEFAULT '{}'::jsonb, UNIQUE(outlet_id,name));
CREATE TABLE IF NOT EXISTS public.restaurant_recipe_ingredients (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, menu_item_id uuid NOT NULL REFERENCES public.restaurant_menu_items(id) ON DELETE CASCADE, inventory_item_id uuid NOT NULL REFERENCES public.inventory_items(id) ON DELETE RESTRICT, quantity numeric(18,4) NOT NULL CHECK(quantity>0), unit text, waste_pct numeric(9,6) NOT NULL DEFAULT 0 CHECK(waste_pct>=0), UNIQUE(menu_item_id,inventory_item_id));
CREATE TABLE IF NOT EXISTS public.restaurant_modifier_groups (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, outlet_id uuid NOT NULL REFERENCES public.restaurant_outlets(id) ON DELETE CASCADE, name text NOT NULL, min_select integer NOT NULL DEFAULT 0, max_select integer NOT NULL DEFAULT 1, status text NOT NULL DEFAULT 'Active', UNIQUE(outlet_id,name));
CREATE TABLE IF NOT EXISTS public.restaurant_modifier_options (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, group_id uuid NOT NULL REFERENCES public.restaurant_modifier_groups(id) ON DELETE CASCADE, inventory_item_id uuid REFERENCES public.inventory_items(id) ON DELETE SET NULL, name text NOT NULL, price_delta numeric(18,2) NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'Active', UNIQUE(group_id,name));
CREATE TABLE IF NOT EXISTS public.restaurant_customers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, guest_id uuid REFERENCES public.hospitality_guests(id) ON DELETE SET NULL, name text NOT NULL, phone text, email text, loyalty_points numeric(18,2) NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'Active', data jsonb NOT NULL DEFAULT '{}'::jsonb, UNIQUE(company_id,phone));
CREATE TABLE IF NOT EXISTS public.restaurant_reservations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, outlet_id uuid NOT NULL REFERENCES public.restaurant_outlets(id) ON DELETE CASCADE, table_id uuid REFERENCES public.restaurant_tables(id) ON DELETE SET NULL, customer_id uuid REFERENCES public.restaurant_customers(id) ON DELETE SET NULL, reference text NOT NULL, reservation_at timestamptz NOT NULL, duration_minutes integer NOT NULL DEFAULT 120 CHECK(duration_minutes>0), covers integer NOT NULL DEFAULT 1 CHECK(covers>0), status text NOT NULL DEFAULT 'Confirmed' CHECK(status IN ('Pending','Confirmed','Seated','Completed','Cancelled','No Show')), notes text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,reference));
CREATE TABLE IF NOT EXISTS public.restaurant_orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, outlet_id uuid NOT NULL REFERENCES public.restaurant_outlets(id) ON DELETE CASCADE, table_id uuid REFERENCES public.restaurant_tables(id) ON DELETE SET NULL, reservation_id uuid REFERENCES public.restaurant_reservations(id) ON DELETE SET NULL, customer_id uuid REFERENCES public.restaurant_customers(id) ON DELETE SET NULL, hotel_folio_id uuid REFERENCES public.hospitality_folios(id) ON DELETE SET NULL, waiter_employee_id uuid REFERENCES public.hr_employees(id) ON DELETE SET NULL, order_number text NOT NULL, order_type text NOT NULL DEFAULT 'Dine In' CHECK(order_type IN ('Dine In','Takeaway','Delivery','Room Charge','Bar')), status text NOT NULL DEFAULT 'Open' CHECK(status IN ('Open','Sent','Preparing','Ready','Served','Paid','Cancelled','Refunded')), subtotal numeric(18,2) NOT NULL DEFAULT 0, discount_amount numeric(18,2) NOT NULL DEFAULT 0, tax_amount numeric(18,2) NOT NULL DEFAULT 0, service_charge_amount numeric(18,2) NOT NULL DEFAULT 0, tip_amount numeric(18,2) NOT NULL DEFAULT 0, total_amount numeric(18,2) NOT NULL DEFAULT 0, currency text NOT NULL DEFAULT 'TZS', opened_at timestamptz NOT NULL DEFAULT now(), closed_at timestamptz, data jsonb NOT NULL DEFAULT '{}'::jsonb, UNIQUE(company_id,order_number));
ALTER TABLE public.restaurant_tables DROP CONSTRAINT IF EXISTS restaurant_tables_current_order_id_fkey;
ALTER TABLE public.restaurant_tables ADD CONSTRAINT restaurant_tables_current_order_id_fkey FOREIGN KEY(current_order_id) REFERENCES public.restaurant_orders(id) ON DELETE SET NULL;
CREATE TABLE IF NOT EXISTS public.restaurant_order_lines (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, order_id uuid NOT NULL REFERENCES public.restaurant_orders(id) ON DELETE CASCADE, menu_item_id uuid REFERENCES public.restaurant_menu_items(id) ON DELETE SET NULL, name text NOT NULL, quantity numeric(18,3) NOT NULL CHECK(quantity>0), unit_price numeric(18,2) NOT NULL CHECK(unit_price>=0), discount_amount numeric(18,2) NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'New' CHECK(status IN ('New','Sent','Preparing','Ready','Served','Voided')), modifiers jsonb NOT NULL DEFAULT '[]'::jsonb, notes text, stock_consumed boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.restaurant_kitchen_tickets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, outlet_id uuid NOT NULL REFERENCES public.restaurant_outlets(id) ON DELETE CASCADE, order_id uuid NOT NULL REFERENCES public.restaurant_orders(id) ON DELETE CASCADE, ticket_number text NOT NULL, station text NOT NULL DEFAULT 'Kitchen', status text NOT NULL DEFAULT 'New' CHECK(status IN ('New','Preparing','Ready','Completed','Cancelled')), opened_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, UNIQUE(company_id,ticket_number));
CREATE TABLE IF NOT EXISTS public.restaurant_payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, order_id uuid NOT NULL REFERENCES public.restaurant_orders(id) ON DELETE RESTRICT, method text NOT NULL CHECK(method IN ('Cash','Card','Mobile Money','Bank Transfer','Room Charge','Customer Credit')), amount numeric(18,2) NOT NULL CHECK(amount>0), reference text, status text NOT NULL DEFAULT 'Captured' CHECK(status IN ('Captured','Refunded','Voided')), received_by uuid DEFAULT auth.uid(), received_at timestamptz NOT NULL DEFAULT now(), data jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS public.restaurant_suppliers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, name text NOT NULL, phone text, email text, address text, status text NOT NULL DEFAULT 'Active', data jsonb NOT NULL DEFAULT '{}'::jsonb, UNIQUE(company_id,name));
CREATE TABLE IF NOT EXISTS public.restaurant_purchase_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, outlet_id uuid NOT NULL REFERENCES public.restaurant_outlets(id) ON DELETE CASCADE, supplier_id uuid REFERENCES public.restaurant_suppliers(id) ON DELETE SET NULL, request_number text NOT NULL, status text NOT NULL DEFAULT 'Draft' CHECK(status IN ('Draft','Submitted','Approved','Received','Cancelled')), total_amount numeric(18,2) NOT NULL DEFAULT 0, currency text NOT NULL DEFAULT 'TZS', data jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,request_number));
CREATE TABLE IF NOT EXISTS public.restaurant_purchase_lines (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, request_id uuid NOT NULL REFERENCES public.restaurant_purchase_requests(id) ON DELETE CASCADE, inventory_item_id uuid NOT NULL REFERENCES public.inventory_items(id) ON DELETE RESTRICT, quantity numeric(18,3) NOT NULL CHECK(quantity>0), unit_cost numeric(18,2) NOT NULL DEFAULT 0, received_quantity numeric(18,3) NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS public.restaurant_wastage (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, outlet_id uuid NOT NULL REFERENCES public.restaurant_outlets(id) ON DELETE CASCADE, inventory_item_id uuid NOT NULL REFERENCES public.inventory_items(id) ON DELETE RESTRICT, quantity numeric(18,3) NOT NULL CHECK(quantity>0), reason text NOT NULL, cost numeric(18,2) NOT NULL DEFAULT 0, created_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.restaurant_alerts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, outlet_id uuid REFERENCES public.restaurant_outlets(id) ON DELETE CASCADE, alert_key text NOT NULL, alert_type text NOT NULL, severity text NOT NULL DEFAULT 'Warning', title text NOT NULL, body text NOT NULL, status text NOT NULL DEFAULT 'Open' CHECK(status IN ('Open','Acknowledged','Resolved')), due_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,alert_key));
CREATE TABLE IF NOT EXISTS public.restaurant_audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, outlet_id uuid REFERENCES public.restaurant_outlets(id) ON DELETE SET NULL, actor_id uuid DEFAULT auth.uid(), action text NOT NULL, subject_type text NOT NULL, subject_id uuid, detail jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());

CREATE INDEX IF NOT EXISTS restaurant_orders_outlet_status_idx ON public.restaurant_orders(company_id,outlet_id,status,opened_at DESC);
CREATE INDEX IF NOT EXISTS restaurant_kitchen_active_idx ON public.restaurant_kitchen_tickets(company_id,outlet_id,status,opened_at);
CREATE INDEX IF NOT EXISTS restaurant_reservations_table_time_idx ON public.restaurant_reservations(company_id,table_id,reservation_at,status);

CREATE OR REPLACE FUNCTION public.restaurant_is_manager() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce((SELECT p.is_active AND lower(p.role) IN ('owner','admin','manager','restaurant_manager','food_beverage_manager','operations_manager','finance_manager','ceo','cfo','super_admin','platform_admin') FROM public.profiles p WHERE p.id=auth.uid()),false) $$;
CREATE OR REPLACE FUNCTION public.restaurant_can_operate(p_roles text[] DEFAULT ARRAY[]::text[]) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.restaurant_is_manager() OR EXISTS(SELECT 1 FROM public.restaurant_staff_roles r JOIN public.hr_employees e ON e.id=r.employee_id JOIN public.profiles p ON p.id=e.profile_id WHERE r.company_id=public.current_company_id() AND r.status='Active' AND e.status='Active' AND p.id=auth.uid() AND p.is_active AND (cardinality(p_roles)=0 OR r.role=ANY(p_roles))) $$;
CREATE OR REPLACE FUNCTION public.restaurant_audit(p_action text,p_subject text,p_id uuid DEFAULT NULL,p_detail jsonb DEFAULT '{}'::jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.restaurant_audit_events(company_id,outlet_id,action,subject_type,subject_id,detail) VALUES(public.current_company_id(),nullif(p_detail->>'outletId','')::uuid,p_action,p_subject,p_id,coalesce(p_detail,'{}'::jsonb)); END $$;

CREATE OR REPLACE FUNCTION public.restaurant_snapshot() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE c uuid:=public.current_company_id(); BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'An authenticated restaurant session is required.' USING ERRCODE='28000'; END IF; RETURN jsonb_build_object('viewer',jsonb_build_object('isManager',public.restaurant_is_manager()),'outlets',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.name) FROM public.restaurant_outlets x WHERE x.company_id=c),'[]'::jsonb),'areas',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.name) FROM public.restaurant_dining_areas x WHERE x.company_id=c),'[]'::jsonb),'tables',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.code) FROM public.restaurant_tables x WHERE x.company_id=c),'[]'::jsonb),'categories',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.sort_order,x.name) FROM public.restaurant_menu_categories x WHERE x.company_id=c),'[]'::jsonb),'menuItems',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.name) FROM public.restaurant_menu_items x WHERE x.company_id=c),'[]'::jsonb),'customers',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.name) FROM public.restaurant_customers x WHERE x.company_id=c LIMIT 200),'[]'::jsonb),'reservations',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.reservation_at DESC) FROM public.restaurant_reservations x WHERE x.company_id=c LIMIT 200),'[]'::jsonb),'orders',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.opened_at DESC) FROM public.restaurant_orders x WHERE x.company_id=c LIMIT 200),'[]'::jsonb),'orderLines',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.created_at) FROM public.restaurant_order_lines x WHERE x.company_id=c),'[]'::jsonb),'tickets',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.opened_at DESC) FROM public.restaurant_kitchen_tickets x WHERE x.company_id=c LIMIT 200),'[]'::jsonb),'payments',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.received_at DESC) FROM public.restaurant_payments x WHERE x.company_id=c LIMIT 200),'[]'::jsonb),'alerts',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC) FROM public.restaurant_alerts x WHERE x.company_id=c AND x.status='Open' LIMIT 100),'[]'::jsonb),'recipes',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM public.restaurant_recipe_ingredients x WHERE x.company_id=c),'[]'::jsonb)); END $$;

CREATE OR REPLACE FUNCTION public.restaurant_action(p_action text,p_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c uuid:=public.current_company_id(); v_id uuid; v_order public.restaurant_orders%ROWTYPE; v_item public.restaurant_menu_items%ROWTYPE; v_line public.restaurant_order_lines%ROWTYPE; v_outlet public.restaurant_outlets%ROWTYPE; v_table public.restaurant_tables%ROWTYPE; v_total numeric:=0; v_subtotal numeric:=0; v_paid numeric:=0; v_inv record; v_qty numeric; v_now timestamptz:=now(); v_ticket uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'An authenticated restaurant session is required.' USING ERRCODE='28000'; END IF;
IF p_action='OUTLET_SAVE' THEN IF NOT public.restaurant_is_manager() THEN RAISE EXCEPTION 'Restaurant manager permission required.' USING ERRCODE='42501'; END IF; INSERT INTO public.restaurant_outlets(company_id,property_id,branch_id,name,code,timezone,currency,tax_rate,service_charge_rate,data) VALUES(c,nullif(p_payload->>'propertyId','')::uuid,nullif(p_payload->>'branchId','')::uuid,coalesce(nullif(p_payload->>'name',''),'Restaurant'),p_payload->>'code',coalesce(p_payload->>'timezone','Africa/Dar_es_Salaam'),coalesce(p_payload->>'currency','TZS'),coalesce(nullif(p_payload->>'taxRate','')::numeric,0),coalesce(nullif(p_payload->>'serviceChargeRate','')::numeric,0),coalesce(p_payload->'data','{}'::jsonb)) RETURNING id INTO v_id;
ELSIF p_action='AREA_SAVE' THEN IF NOT public.restaurant_is_manager() THEN RAISE EXCEPTION 'Restaurant manager permission required.'; END IF; INSERT INTO public.restaurant_dining_areas(company_id,outlet_id,name,area_type,layout) VALUES(c,(p_payload->>'outletId')::uuid,coalesce(nullif(p_payload->>'name',''),'Dining'),coalesce(p_payload->>'areaType','Dining'),coalesce(p_payload->'layout','{}'::jsonb)) RETURNING id INTO v_id;
ELSIF p_action='TABLE_SAVE' THEN IF NOT public.restaurant_is_manager() THEN RAISE EXCEPTION 'Restaurant manager permission required.'; END IF; INSERT INTO public.restaurant_tables(company_id,outlet_id,area_id,code,capacity,position,data) VALUES(c,(p_payload->>'outletId')::uuid,nullif(p_payload->>'areaId','')::uuid,coalesce(nullif(p_payload->>'code',''),'Table'),coalesce(nullif(p_payload->>'capacity','')::integer,2),coalesce(p_payload->'position','{}'::jsonb),coalesce(p_payload->'data','{}'::jsonb)) RETURNING id INTO v_id;
ELSIF p_action='CATEGORY_SAVE' THEN IF NOT public.restaurant_is_manager() THEN RAISE EXCEPTION 'Restaurant manager permission required.'; END IF; INSERT INTO public.restaurant_menu_categories(company_id,outlet_id,name,sort_order) VALUES(c,(p_payload->>'outletId')::uuid,coalesce(nullif(p_payload->>'name',''),'Menu'),coalesce(nullif(p_payload->>'sortOrder','')::integer,0)) RETURNING id INTO v_id;
ELSIF p_action='MENU_ITEM_SAVE' THEN IF NOT public.restaurant_is_manager() THEN RAISE EXCEPTION 'Restaurant manager permission required.'; END IF; INSERT INTO public.restaurant_menu_items(company_id,outlet_id,category_id,inventory_item_id,sku,name,description,price,cost_price,preparation_minutes,station,tax_rate,data) VALUES(c,(p_payload->>'outletId')::uuid,nullif(p_payload->>'categoryId','')::uuid,nullif(p_payload->>'inventoryItemId','')::uuid,p_payload->>'sku',coalesce(nullif(p_payload->>'name',''),'Menu item'),p_payload->>'description',coalesce(nullif(p_payload->>'price','')::numeric,0),coalesce(nullif(p_payload->>'costPrice','')::numeric,0),coalesce(nullif(p_payload->>'preparationMinutes','')::integer,0),coalesce(p_payload->>'station','Kitchen'),nullif(p_payload->>'taxRate','')::numeric,coalesce(p_payload->'data','{}'::jsonb)) RETURNING id INTO v_id;
ELSIF p_action='RECIPE_INGREDIENT_SAVE' THEN IF NOT public.restaurant_is_manager() THEN RAISE EXCEPTION 'Restaurant manager permission required.'; END IF; INSERT INTO public.restaurant_recipe_ingredients(company_id,menu_item_id,inventory_item_id,quantity,unit,waste_pct) VALUES(c,(p_payload->>'menuItemId')::uuid,(p_payload->>'inventoryItemId')::uuid,(p_payload->>'quantity')::numeric,p_payload->>'unit',coalesce(nullif(p_payload->>'wastePct','')::numeric,0)) ON CONFLICT(menu_item_id,inventory_item_id) DO UPDATE SET quantity=excluded.quantity,unit=excluded.unit,waste_pct=excluded.waste_pct RETURNING id INTO v_id;
ELSIF p_action='CUSTOMER_SAVE' THEN IF NOT public.restaurant_can_operate(ARRAY['Cashier','Waiter','Restaurant Manager']) THEN RAISE EXCEPTION 'Restaurant customer permission required.'; END IF; INSERT INTO public.restaurant_customers(company_id,guest_id,name,phone,email,data) VALUES(c,nullif(p_payload->>'guestId','')::uuid,coalesce(nullif(p_payload->>'name',''),'Walk-in'),nullif(p_payload->>'phone',''),nullif(p_payload->>'email',''),coalesce(p_payload->'data','{}'::jsonb)) RETURNING id INTO v_id;
ELSIF p_action='RESERVATION_CREATE' THEN IF NOT public.restaurant_can_operate(ARRAY['Cashier','Waiter','Restaurant Manager']) THEN RAISE EXCEPTION 'Restaurant reservation permission required.'; END IF; IF EXISTS(SELECT 1 FROM public.restaurant_reservations r WHERE r.company_id=c AND r.table_id=nullif(p_payload->>'tableId','')::uuid AND r.status IN ('Confirmed','Seated') AND r.reservation_at < (p_payload->>'reservationAt')::timestamptz + interval '2 hours' AND r.reservation_at + r.duration_minutes*interval '1 minute' > (p_payload->>'reservationAt')::timestamptz) THEN RAISE EXCEPTION 'The selected table is already reserved for this time.' USING ERRCODE='23P01'; END IF; INSERT INTO public.restaurant_reservations(company_id,outlet_id,table_id,customer_id,reference,reservation_at,duration_minutes,covers,notes) VALUES(c,(p_payload->>'outletId')::uuid,nullif(p_payload->>'tableId','')::uuid,nullif(p_payload->>'customerId','')::uuid,coalesce(nullif(p_payload->>'reference',''),'RSV-'||to_char(v_now,'YYYYMMDD')||'-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,6))),(p_payload->>'reservationAt')::timestamptz,coalesce(nullif(p_payload->>'durationMinutes','')::integer,120),coalesce(nullif(p_payload->>'covers','')::integer,1),p_payload->>'notes') RETURNING id INTO v_id;
ELSIF p_action='ORDER_OPEN' THEN IF NOT public.restaurant_can_operate(ARRAY['Cashier','Waiter','Restaurant Manager','Bar']) THEN RAISE EXCEPTION 'Restaurant order permission required.'; END IF; IF nullif(p_payload->>'tableId','') IS NOT NULL THEN SELECT * INTO v_table FROM public.restaurant_tables WHERE id=(p_payload->>'tableId')::uuid AND company_id=c FOR UPDATE; IF NOT FOUND OR v_table.status NOT IN ('Available','Reserved') THEN RAISE EXCEPTION 'The selected table is not available.' USING ERRCODE='55000'; END IF; END IF; INSERT INTO public.restaurant_orders(company_id,outlet_id,table_id,reservation_id,customer_id,hotel_folio_id,waiter_employee_id,order_number,order_type,currency,data) VALUES(c,(p_payload->>'outletId')::uuid,nullif(p_payload->>'tableId','')::uuid,nullif(p_payload->>'reservationId','')::uuid,nullif(p_payload->>'customerId','')::uuid,nullif(p_payload->>'hotelFolioId','')::uuid,nullif(p_payload->>'waiterEmployeeId','')::uuid,coalesce(nullif(p_payload->>'orderNumber',''),'RFO-'||to_char(v_now,'YYYYMMDD')||'-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,6))),coalesce(p_payload->>'orderType','Dine In'),coalesce(p_payload->>'currency','TZS'),coalesce(p_payload->'data','{}'::jsonb)) RETURNING * INTO v_order; v_id:=v_order.id; IF v_order.table_id IS NOT NULL THEN UPDATE public.restaurant_tables SET status='Occupied',current_order_id=v_id,updated_at=v_now WHERE id=v_order.table_id; END IF;
ELSIF p_action='ORDER_ADD_LINE' THEN IF NOT public.restaurant_can_operate(ARRAY['Cashier','Waiter','Restaurant Manager','Bar']) THEN RAISE EXCEPTION 'Restaurant order permission required.'; END IF; SELECT * INTO v_order FROM public.restaurant_orders WHERE id=(p_payload->>'orderId')::uuid AND company_id=c FOR UPDATE; IF NOT FOUND OR v_order.status NOT IN ('Open','Sent') THEN RAISE EXCEPTION 'Only an open order can be edited.' USING ERRCODE='55000'; END IF; SELECT * INTO v_item FROM public.restaurant_menu_items WHERE id=(p_payload->>'menuItemId')::uuid AND company_id=c AND status='Active'; IF NOT FOUND THEN RAISE EXCEPTION 'The selected menu item is unavailable.' USING ERRCODE='P0002'; END IF; INSERT INTO public.restaurant_order_lines(company_id,order_id,menu_item_id,name,quantity,unit_price,modifiers,notes) VALUES(c,v_order.id,v_item.id,v_item.name,coalesce(nullif(p_payload->>'quantity','')::numeric,1),v_item.price,coalesce(p_payload->'modifiers','[]'::jsonb),p_payload->>'notes') RETURNING id INTO v_id; UPDATE public.restaurant_orders SET subtotal=(SELECT coalesce(sum(quantity*unit_price-discount_amount),0) FROM public.restaurant_order_lines WHERE order_id=v_order.id),total_amount=(SELECT coalesce(sum(quantity*unit_price-discount_amount),0) FROM public.restaurant_order_lines WHERE order_id=v_order.id) WHERE id=v_order.id;
ELSIF p_action='ORDER_SEND_KITCHEN' THEN IF NOT public.restaurant_can_operate(ARRAY['Cashier','Waiter','Restaurant Manager','Bar']) THEN RAISE EXCEPTION 'Restaurant order permission required.'; END IF; SELECT * INTO v_order FROM public.restaurant_orders WHERE id=(p_payload->>'orderId')::uuid AND company_id=c FOR UPDATE; IF NOT FOUND OR v_order.status NOT IN ('Open','Sent') THEN RAISE EXCEPTION 'Only an open order can be sent to kitchen.' USING ERRCODE='55000'; END IF; FOR v_line IN SELECT * FROM public.restaurant_order_lines WHERE order_id=v_order.id AND status='New' FOR UPDATE LOOP FOR v_inv IN SELECT ri.quantity*(1+ri.waste_pct/100)*v_line.quantity AS consume_qty,i.id,i.name,coalesce(nullif(i.data->>'qty_on_hand','')::numeric,nullif(i.data->>'quantity','')::numeric,0) AS stock FROM public.restaurant_recipe_ingredients ri JOIN public.inventory_items i ON i.id=ri.inventory_item_id WHERE ri.menu_item_id=v_line.menu_item_id AND ri.company_id=c FOR UPDATE LOOP IF v_inv.stock<v_inv.consume_qty THEN RAISE EXCEPTION 'Insufficient recipe stock for %.',v_inv.name USING ERRCODE='P0001'; END IF; UPDATE public.inventory_items SET data=jsonb_set(data,'{qty_on_hand}',to_jsonb(v_inv.stock-v_inv.consume_qty),true),updated_at=v_now WHERE id=v_inv.id; INSERT INTO public.inventory_stock_movements(company_id,name,status,amount,notes,data) VALUES(c,v_inv.name,'Out',v_inv.consume_qty,'Restaurant recipe consumption',jsonb_build_object('source','restaurant_order_line','order_line_id',v_line.id,'order_id',v_order.id,'movement','Out','qty',v_inv.consume_qty)); END LOOP; UPDATE public.restaurant_order_lines SET status='Sent',stock_consumed=true WHERE id=v_line.id; END LOOP; INSERT INTO public.restaurant_kitchen_tickets(company_id,outlet_id,order_id,ticket_number,station,status) SELECT c,v_order.outlet_id,v_order.id,'KDS-'||to_char(v_now,'YYYYMMDD')||'-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,6)),coalesce((SELECT station FROM public.restaurant_menu_items mi JOIN public.restaurant_order_lines ol ON ol.menu_item_id=mi.id WHERE ol.order_id=v_order.id ORDER BY ol.created_at LIMIT 1),'Kitchen'),'New' RETURNING id INTO v_ticket; UPDATE public.restaurant_orders SET status='Sent' WHERE id=v_order.id; v_id:=v_ticket;
ELSIF p_action='KITCHEN_TRANSITION' THEN IF NOT public.restaurant_can_operate(ARRAY['Kitchen','Bar','Restaurant Manager']) THEN RAISE EXCEPTION 'Kitchen or manager permission required.'; END IF; UPDATE public.restaurant_kitchen_tickets SET status=CASE upper(coalesce(p_payload->>'status','')) WHEN 'PREPARING' THEN 'Preparing' WHEN 'READY' THEN 'Ready' WHEN 'COMPLETED' THEN 'Completed' WHEN 'CANCELLED' THEN 'Cancelled' ELSE NULL END,completed_at=CASE WHEN upper(p_payload->>'status')='COMPLETED' THEN v_now ELSE NULL END WHERE id=(p_payload->>'ticketId')::uuid AND company_id=c RETURNING id,order_id INTO v_id,v_ticket; IF v_id IS NULL THEN RAISE EXCEPTION 'Kitchen ticket not found.' USING ERRCODE='P0002'; END IF; UPDATE public.restaurant_orders SET status=CASE upper(p_payload->>'status') WHEN 'PREPARING' THEN 'Preparing' WHEN 'READY' THEN 'Ready' WHEN 'COMPLETED' THEN 'Served' ELSE status END WHERE id=v_ticket; UPDATE public.restaurant_order_lines SET status=CASE upper(p_payload->>'status') WHEN 'PREPARING' THEN 'Preparing' WHEN 'READY' THEN 'Ready' WHEN 'COMPLETED' THEN 'Served' ELSE status END WHERE order_id=v_ticket AND status<>'Voided';
ELSIF p_action='ORDER_SETTLE' THEN IF NOT public.restaurant_can_operate(ARRAY['Cashier','Restaurant Manager','Finance']) THEN RAISE EXCEPTION 'Cashier or manager permission required.'; END IF; SELECT * INTO v_order FROM public.restaurant_orders WHERE id=(p_payload->>'orderId')::uuid AND company_id=c FOR UPDATE; SELECT * INTO v_outlet FROM public.restaurant_outlets WHERE id=v_order.outlet_id AND company_id=c; IF NOT FOUND OR v_order.status NOT IN ('Ready','Served','Preparing') THEN RAISE EXCEPTION 'Only prepared or served orders can be settled.' USING ERRCODE='55000'; END IF; v_subtotal:=coalesce((SELECT sum(quantity*unit_price-discount_amount) FROM public.restaurant_order_lines WHERE order_id=v_order.id AND status<>'Voided'),0); v_total:=round((v_subtotal-coalesce(nullif(p_payload->>'discountAmount','')::numeric,0))*(1+coalesce(v_outlet.tax_rate,0)/100+coalesce(v_outlet.service_charge_rate,0)/100)+coalesce(nullif(p_payload->>'tipAmount','')::numeric,0),2); IF jsonb_typeof(p_payload->'payments')<>'array' OR jsonb_array_length(p_payload->'payments')=0 THEN RAISE EXCEPTION 'At least one payment allocation is required.' USING ERRCODE='22023'; END IF; SELECT coalesce(sum((value->>'amount')::numeric),0) INTO v_paid FROM jsonb_array_elements(p_payload->'payments'); IF v_paid<v_total THEN RAISE EXCEPTION 'Payment allocations do not cover the final total.' USING ERRCODE='22023'; END IF; FOR v_inv IN SELECT value FROM jsonb_array_elements(p_payload->'payments') LOOP IF coalesce(v_inv.value->>'method','') NOT IN ('Cash','Card','Mobile Money','Bank Transfer','Room Charge','Customer Credit') OR coalesce((v_inv.value->>'amount')::numeric,0)<=0 THEN RAISE EXCEPTION 'Invalid payment allocation.' USING ERRCODE='22023'; END IF; INSERT INTO public.restaurant_payments(company_id,order_id,method,amount,reference,data) VALUES(c,v_order.id,v_inv.value->>'method',(v_inv.value->>'amount')::numeric,v_inv.value->>'reference',jsonb_build_object('tendered_amount',(v_inv.value->>'amount')::numeric)); END LOOP; IF v_order.hotel_folio_id IS NOT NULL AND EXISTS(SELECT 1 FROM jsonb_array_elements(p_payload->'payments') x WHERE x->>'method'='Room Charge') THEN INSERT INTO public.hospitality_folio_lines(company_id,folio_id,line_type,description,quantity,unit_amount,amount,currency,source_table,source_record_id,data) VALUES(c,v_order.hotel_folio_id,'Dining','Restaurant order '||v_order.order_number,1,v_total,v_total,v_order.currency,'restaurant_orders',v_order.id,jsonb_build_object('restaurantOrderId',v_order.id)); END IF; UPDATE public.restaurant_orders SET subtotal=v_subtotal,discount_amount=coalesce(nullif(p_payload->>'discountAmount','')::numeric,0),tax_amount=round((v_subtotal-coalesce(nullif(p_payload->>'discountAmount','')::numeric,0))*v_outlet.tax_rate/100,2),service_charge_amount=round((v_subtotal-coalesce(nullif(p_payload->>'discountAmount','')::numeric,0))*v_outlet.service_charge_rate/100,2),tip_amount=coalesce(nullif(p_payload->>'tipAmount','')::numeric,0),total_amount=v_total,status='Paid',closed_at=v_now WHERE id=v_order.id; INSERT INTO public.pos_transactions(company_id,name,status,amount,notes,data) VALUES(c,'Restaurant '||v_order.order_number,'Completed',v_total,'Restaurant settlement',jsonb_build_object('source','restaurant_order','order_id',v_order.id,'doc_number',v_order.order_number,'subtotal',v_subtotal,'tax',round((v_subtotal-coalesce(nullif(p_payload->>'discountAmount','')::numeric,0))*v_outlet.tax_rate/100,2),'total',v_total)) RETURNING id INTO v_id; INSERT INTO public.journal_entries(company_id,name,status,amount,notes,data) VALUES(c,'Restaurant revenue: '||v_order.order_number,'Posted',v_total,'Restaurant order settlement',jsonb_build_object('source','restaurant_order','order_id',v_order.id,'currency',v_order.currency)); IF v_order.table_id IS NOT NULL THEN UPDATE public.restaurant_tables SET status='Cleaning',current_order_id=NULL,updated_at=v_now WHERE id=v_order.table_id; END IF;
ELSIF p_action='TABLE_RELEASE' THEN IF NOT public.restaurant_can_operate(ARRAY['Waiter','Cashier','Restaurant Manager']) THEN RAISE EXCEPTION 'Restaurant operations permission required.'; END IF; UPDATE public.restaurant_tables SET status='Available',current_order_id=NULL,updated_at=v_now WHERE id=(p_payload->>'tableId')::uuid AND company_id=c RETURNING id INTO v_id;
ELSIF p_action='WASTAGE_LOG' THEN IF NOT public.restaurant_can_operate(ARRAY['Storekeeper','Restaurant Manager','Kitchen']) THEN RAISE EXCEPTION 'Restaurant stock permission required.'; END IF; SELECT i.id,i.name,coalesce(nullif(i.data->>'qty_on_hand','')::numeric,nullif(i.data->>'quantity','')::numeric,0) AS stock INTO v_inv FROM public.inventory_items i WHERE i.id=(p_payload->>'inventoryItemId')::uuid AND i.company_id=c FOR UPDATE; v_qty:=(p_payload->>'quantity')::numeric; IF NOT FOUND OR v_qty<=0 OR v_inv.stock<v_qty THEN RAISE EXCEPTION 'Valid available inventory is required for wastage.' USING ERRCODE='22023'; END IF; UPDATE public.inventory_items SET data=jsonb_set(data,'{qty_on_hand}',to_jsonb(v_inv.stock-v_qty),true),updated_at=v_now WHERE id=v_inv.id; INSERT INTO public.restaurant_wastage(company_id,outlet_id,inventory_item_id,quantity,reason,cost) VALUES(c,(p_payload->>'outletId')::uuid,v_inv.id,v_qty,coalesce(nullif(p_payload->>'reason',''),'Wastage'),coalesce(nullif(p_payload->>'cost','')::numeric,0)) RETURNING id INTO v_id; INSERT INTO public.inventory_stock_movements(company_id,name,status,amount,notes,data) VALUES(c,v_inv.name,'Out',v_qty,'Restaurant wastage',jsonb_build_object('source','restaurant_wastage','wastage_id',v_id,'movement','Out','qty',v_qty));
ELSE RAISE EXCEPTION 'Unsupported restaurant action: %',p_action USING ERRCODE='22023'; END IF; PERFORM public.restaurant_audit(p_action,split_part(p_action,'_',1),v_id,p_payload); RETURN jsonb_build_object('ok',true,'action',p_action,'recordId',v_id,'snapshotRequired',true); END $$;

CREATE OR REPLACE FUNCTION public.restaurant_reconcile_alerts(p_company_id uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c uuid:=coalesce(p_company_id,public.current_company_id()); n integer:=0; r record; BEGIN IF p_company_id IS NOT NULL AND auth.role()<>'service_role' THEN RAISE EXCEPTION 'Service role required for explicit restaurant alert reconciliation.' USING ERRCODE='42501'; END IF; FOR r IN SELECT i.id,i.name,coalesce(nullif(i.data->>'qty_on_hand','')::numeric,nullif(i.data->>'quantity','')::numeric,0) qty,coalesce(nullif(i.data->>'reorder_level','')::numeric,0) reorder FROM public.inventory_items i WHERE i.company_id=c AND coalesce(nullif(i.data->>'reorder_level','')::numeric,0)>0 LOOP IF r.qty<=r.reorder THEN INSERT INTO public.restaurant_alerts(company_id,alert_key,alert_type,severity,title,body) VALUES(c,'low-stock:'||r.id,'Low stock','Warning','Low stock: '||r.name,'On-hand quantity is at or below the configured reorder level.') ON CONFLICT(company_id,alert_key) DO UPDATE SET status='Open',created_at=now(); n:=n+1; END IF; END LOOP; RETURN jsonb_build_object('ok',true,'alerts',n); END $$;

DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['restaurant_outlets','restaurant_dining_areas','restaurant_tables','restaurant_staff_roles','restaurant_shifts','restaurant_menu_categories','restaurant_menu_items','restaurant_recipe_ingredients','restaurant_modifier_groups','restaurant_modifier_options','restaurant_customers','restaurant_reservations','restaurant_orders','restaurant_order_lines','restaurant_kitchen_tickets','restaurant_payments','restaurant_suppliers','restaurant_purchase_requests','restaurant_purchase_lines','restaurant_wastage','restaurant_alerts','restaurant_audit_events'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I',t||'_tenant_read',t); EXECUTE format('CREATE POLICY %I ON public.%I FOR SELECT TO authenticated USING (company_id=public.current_company_id())',t||'_tenant_read',t); END LOOP; END $$;
REVOKE ALL ON FUNCTION public.restaurant_is_manager() FROM PUBLIC,anon; REVOKE ALL ON FUNCTION public.restaurant_can_operate(text[]) FROM PUBLIC,anon; REVOKE ALL ON FUNCTION public.restaurant_audit(text,text,uuid,jsonb) FROM PUBLIC,anon,authenticated; REVOKE ALL ON FUNCTION public.restaurant_snapshot() FROM PUBLIC,anon; REVOKE ALL ON FUNCTION public.restaurant_action(text,jsonb) FROM PUBLIC,anon; REVOKE ALL ON FUNCTION public.restaurant_reconcile_alerts(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.restaurant_snapshot() TO authenticated; GRANT EXECUTE ON FUNCTION public.restaurant_action(text,jsonb) TO authenticated; GRANT EXECUTE ON FUNCTION public.restaurant_reconcile_alerts(uuid) TO service_role;
COMMIT;
